from acmesdk.auth import collect_policy
result = collect_policy({'id': 6, 'name': 'harbor', 'tier': 'b'}, ['id', 'name', 'owner'])
result = {k: v for k, v in result.items() if v is not None}
assert result == {'id': 6, 'name': 'harbor'}
print('Success')
